def _read_existing(path: str) -> bytes | None:
    # None records that the file did not exist; a file's bytes may
    # themselves be empty in principle, so an empty b"" is not the same
    # answer. Any read error other than a missing file is swallowed by the
    # callers auditing departure bytes, so measuring the target can never
    # mask or replace the operation's own exception.
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except FileNotFoundError:
        return None

